CREATE TEMPORARY VIEW cheapest_list_${grass_region_without_quote} AS
select
     cspu_id
    ,item_id
    ,exp_tag
from(
    SELECT
         cspu_id
        ,item_id
    FROM srdi_mart.dwd_sr_data_warehouse_pb_one_variation_model_minf
    where grass_region in (${grass_region}) and regional_date=${regional_date} and regional_hour=${regional_hour}
    group by 1,2
) a
lateral view explode(array('exp_1')) b as exp_tag -- 按照实验策略数量，进行维表复制拷贝，v2的第一次发版只有一个实验策略
;
--sql_divide_splitter--
-- 获取最近7天，最大可用且<当前小时的分区，以此获取上一个可用的历史分区，还会外加质量检测：>5%的版本日期=（当日+昨日）就报错
-- 所以这个表也得设置成单并发度任务。
set last_partition_${grass_region_without_quote} = (
select
    max(time_str)
from(
    SELECT
        concat(regional_date,'_',if(regional_hour<10,concat('0',regional_hour),regional_hour)) as  time_str
    FROM srdi_mart.dwd_sr_data_warehouse_pb_search_replace_pruning_hf
    where grass_region in (${grass_region}) and regional_date between date_sub(${regional_date}, 6) and ${regional_date}
    group by regional_date,regional_hour
) a
where time_str<concat(${regional_date},'_',if(${regional_hour}<10,concat('0',${regional_hour}),${regional_hour}))
);
--sql_divide_splitter--

CREATE TEMPORARY VIEW last_pruning_${grass_region_without_quote} AS
SELECT
     exp_tag
    ,cspu_id
    ,item_id
    ,version_date
    ,pruning_tag
FROM srdi_mart.dwd_sr_data_warehouse_pb_search_replace_pruning_hf
where grass_region in (${grass_region}) and regional_date = split(${last_partition_${grass_region_without_quote}},'_')[0]
and regional_hour = cast(split(${last_partition_${grass_region_without_quote}},'_')[1] as int)
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW accumulated_pruning_list_${grass_region_without_quote} AS
SELECT -- 用来扩充新的组合key
     if(a.exp_tag is not null ,a.exp_tag,b.exp_tag) as exp_tag
    ,if(a.cspu_id is not null ,a.cspu_id,b.cspu_id) as cspu_id
    ,if(a.item_id is not null ,a.item_id,b.item_id) as item_id
    ,a.version_date
    ,a.pruning_tag
FROM last_pruning_${grass_region_without_quote} a
full outer join cheapest_list_${grass_region_without_quote} b on a.item_id=b.item_id and a.cspu_id=b.cspu_id and a.exp_tag=b.exp_tag
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW scheduler_pruning_${grass_region_without_quote} AS
SELECT
     item_id
    ,coalesce(item_imp_cnt_7d,0) as item_imp_cnt_7d
    ,coalesce(item_order_cnt_7d,0) as item_order_cnt_7d
    ,coalesce(cspu_exclude_self_imp_cnt_7d,0) as cspu_exclude_self_imp_cnt_7d
    ,coalesce(cspu_exclude_self_ads_imp_cnt_7d/7,0) as cspu_exclude_self_ads_imp_cnt_avg
    ,coalesce(item_click_cnt_7d/item_imp_cnt_7d,0) as item_ctr_l7d
    ,coalesce(cspu_exclude_self_click_cnt_7d/cspu_exclude_self_imp_cnt_7d,0) as cspu_ctr_l7d
    ,coalesce(item_order_cnt_7d/item_imp_cnt_7d,0) as item_ctcr_l7d
    ,coalesce(cspu_exclude_self_order_cnt_7d/cspu_exclude_self_imp_cnt_7d,0) as cspu_ctcr_l7d
FROM srdi_mart.dws_sr_data_warehouse_pb_replace_pruning_item_nd
where grass_region in (${grass_region}) and mapping_general='Search'
and local_date = data_infra.max_pt('srdi_mart.dws_sr_data_warehouse_pb_replace_pruning_item_nd', 'local_date', "grass_region=${grass_region} and local_date<${regional_date}")
and last7d_day_cnt>=7 -- 防止纯新item数据少，数据不置信，造成判定失误。
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW manual_pruning_${grass_region_without_quote} AS
select
    a.*
from(
    SELECT
         item_id
        ,coalesce(item_imp_cnt_7d,0) as item_imp_cnt_7d
        ,coalesce(item_order_cnt_7d,0) as item_order_cnt_7d
        ,coalesce(cspu_exclude_self_imp_cnt_7d,0) as cspu_exclude_self_imp_cnt_7d
        ,coalesce(cspu_exclude_self_ads_imp_cnt_7d/7,0) as cspu_exclude_self_ads_imp_cnt_avg
        ,coalesce(item_click_cnt_7d/item_imp_cnt_7d,0) as item_ctr_l7d
        ,coalesce(cspu_exclude_self_click_cnt_7d/cspu_exclude_self_imp_cnt_7d,0) as cspu_ctr_l7d
        ,coalesce(item_order_cnt_7d/item_imp_cnt_7d,0) as item_ctcr_l7d
        ,coalesce(cspu_exclude_self_order_cnt_7d/cspu_exclude_self_imp_cnt_7d,0) as cspu_ctcr_l7d
    FROM srdi_mart.dws_sr_data_warehouse_pb_replace_pruning_item_manual_7d
    where grass_region in (${grass_region}) and mapping_general='Search'
    and local_date = data_infra.max_pt('srdi_mart.dws_sr_data_warehouse_pb_replace_pruning_item_manual_7d', 'local_date', "grass_region=${grass_region} and local_date<${regional_date}")
    and local_date >= date_sub(${regional_date}, 2) --如果手动任务一天没跑完，就用昨天的
) a
left join scheduler_pruning_${grass_region_without_quote} b on a.item_id=b.item_id
where b.item_id is null -- 如果例行有，优先用例行的结果
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW pruning_basic_metrics_${grass_region_without_quote} AS
