     item_id
    ,item_imp_cnt_7d
    ,item_order_cnt_7d
    ,cspu_exclude_self_imp_cnt_7d
    ,cspu_exclude_self_ads_imp_cnt_avg
    ,item_ctr_l7d
    ,cspu_ctr_l7d
    ,item_ctcr_l7d
    ,cspu_ctcr_l7d
from scheduler_pruning_${grass_region_without_quote}
union all
