CREATE TEMPORARY VIEW pruning_exp_${grass_region_without_quote} AS
select
     'exp_1' as exp_tag
    ,item_id
    ,case
        when item_imp_cnt_7d < 500 or cspu_exclude_self_imp_cnt_7d < 500 then if(cspu_exclude_self_ads_imp_cnt_avg<100,'can_not_explore','long_tail')
        when item_order_cnt_7d =0 then 'obvious_bad'
        when item_imp_cnt_7d < 2000 then
             case
               when item_ctr_l7d > 1.3*cspu_ctr_l7d then 'obvious_good'
               when item_ctr_l7d < 0.7*cspu_ctr_l7d then 'obvious_bad'
               else 'same_with_cspu'
             end
        else
             case
               when item_ctcr_l7d > 1.3*cspu_ctcr_l7d then 'obvious_good'
               when item_ctcr_l7d < 0.7*cspu_ctcr_l7d then 'obvious_bad'
               else 'same_with_cspu'
             end
     end as pruning_tag
from pruning_basic_metrics_${grass_region_without_quote}
