-- 不依赖marker，也不采用最大可用分区，如果错过了今天的窗口期，就等后天再送一次
CREATE TEMPORARY VIEW monitoring_back_${grass_region_without_quote} AS
SELECT -- 这个表拿不到数据也没关系，就是错过今日的监控回退而已，明天还会继续的。
     exp_tag
    ,item_id
    ,cspu_id
    ,version_date
FROM srdi_mart.dwd_sr_data_warehouse_pb_search_replace_monitoring_nd
where grass_region in (${grass_region}) and local_date = date_sub(${regional_date}, 1)
and version_date =replace(${regional_date}, '-', '') -- 数值=今天是新需要升级的，如果升版本流程失败，那么隔一天还会再进入新分区里，例如：1号的那一批，刘鹏没有收到，2号我这里就没他们了，但是3号就又有了
;
--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dwd_sr_data_warehouse_pb_search_replace_pruning_hf
PARTITION (grass_region = ${grass_region}, regional_date = ${regional_date}, regional_hour = ${regional_hour})
SELECT
     d.exp_tag
    ,d.cspu_id
    ,d.item_id
    ,if(update_flag
        ,new_pruning_tag
        ,current_pruning_tag
      ) as pruning_tag
    ,if(update_flag
       ,if(new_pruning_tag is not null
          ,cast(replace(${regional_date}, '-', '') as int) -- 纯新的或者要求升级的，给定一个版本值
          ,null --没有的等待质检信息
          )
       ,current_version_date
     ) as version_date --版本信息是线上流转的关键信息之一。
from (
    select
         a.exp_tag
        ,a.cspu_id
        ,a.item_id
        ,if( (b.version_date is not null and b.version_date > coalesce(a.version_date,0)) --需要版本升级的；截止20250903的需求逻辑，如果new_version_date不是null，那么d.version_date理论也不会是null
             or
             (a.version_date is null) --这里其实包含两种：1）本次运行新补充的；2）上次运行没有质检信息的
           ,true
           ,false
         ) as update_flag
        ,a.pruning_tag  as current_pruning_tag
        ,a.version_date as current_version_date
        ,c.pruning_tag  as new_pruning_tag
        ,b.version_date as new_version_date
    from accumulated_pruning_list_${grass_region_without_quote} a
    left join monitoring_back_${grass_region_without_quote} b on a.item_id=b.item_id and a.cspu_id=b.cspu_id and a.exp_tag=b.exp_tag
    left join pruning_exp_${grass_region_without_quote} c on a.item_id=c.item_id and a.exp_tag=c.exp_tag
) d
;
